// AD4-KEY-CHECK
// THE KEY IS NOT IN THIS FILE ANY MORE, AND THAT IS THE POINT.
//
// Every Supabase node in this workflow authenticates with an n8n SUPABASE
// CREDENTIAL rather than a key pasted into the Config node. That is one place
// to set it instead of twelve, it is encrypted at rest in n8n, and exporting
// this workflow can no longer leak it - the old shape had the service key
// sitting in plain text inside a JSON file that gets emailed around.
//
// SET IT UP ONCE, BEFORE IMPORTING ANYTHING:
//   n8n -> Credentials -> New -> Supabase API
//     Name         AD4 Supabase        <- this name exactly
//     Host         https://<your-project-ref>.supabase.co
//     Service Role the SERVICE ROLE key (Project Settings -> API keys)
//
// The name matters because every Supabase node in every AD4 workflow is
// already bound to a credential called AD4 Supabase. Create it first and
// n8n links all of them on import - nothing to pick node by node. Import
// first and the nodes come in unbound, and you pick the credential on each
// one by hand; it works, it is just ~57 dropdowns instead of zero.
//
// The credential sends `apikey` and `Authorization: Bearer` itself, which is
// exactly what these nodes used to set by hand.
//
// WHAT STILL CHECKS THE KEY. This node can no longer read it - a credential
// is not visible to an expression, by design. Two things downstream do:
//
//   the schedule gate, immediately below. sql/ad4_38 revokes should_run from
//   anon, so a credential holding the publishable key is refused HERE, two
//   nodes in, before a single row is fetched.
//
//   the write guard in the Summary node, which names any refusal the
//   database gives and refuses to report success on a run that wrote nothing.
//
// supabase_url stays in Config because an expression has to build the request
// URL and cannot read the credential's host. It is not a secret.
{
  const cfg = $('Config').first().json ?? {};
  const url = String(cfg.supabase_url ?? '').trim();
  if (!url) {
    throw new Error(
      'Config -> supabase_url is empty. Set it to exactly ' +
      'https://<your-project-ref>.supabase.co - no trailing slash and no /rest/v1, ' +
      'which every node below appends itself. The KEY does not go here: it belongs in ' +
      'the n8n Supabase credential (Credentials -> New -> Supabase API), which is ' +
      'where the nodes now read it from.');
  }
  if (!/^https:\/\//.test(url) || /\/rest\b/.test(url) || /\/$/.test(url)) {
    throw new Error(
      `Config -> supabase_url is "${url}", which is not the shape every node below ` +
      'expects: https://<your-project-ref>.supabase.co, no trailing slash, no /rest/v1. ' +
      'Nothing was fetched and nothing was written.');
  }
}

// AD4-KEY-CHECK
// A TOKEN THAT CAN START A BUILD IS NOT A SUPABASE KEY.
//
// This workflow is the one place in AD4 that holds a GitHub token, and it is
// deliberately the only one: the browser button that calls it holds nothing.
// A page that could start a workflow on its own would be a page carrying a
// credential, and that credential would end up in the bundle.
//
// So the checks here are about the GitHub side, not the database side. Nothing
// below prints, returns or logs the token.
{
  const cfg = $('Config').first().json ?? {};
  const need = ['github_owner', 'github_repo', 'github_token'];
  const missing = need.filter((k) => !String(cfg[k] ?? '').trim());
  if (missing.length) {
    throw new Error(
      `Config.${missing.join(' and Config.')} is empty. This workflow asks GitHub to run the ` +
      `learning Actions, so it needs the repository and a token with the "actions: write" ` +
      `permission - a fine-grained personal access token scoped to that one repository is ` +
      `enough. Put it in Config -> github_token here in n8n and NOWHERE ELSE: not in Vercel, ` +
      `not in any NEXT_PUBLIC_ variable, not in the browser.`);
  }
  const tok = String(cfg.github_token).trim();
  if (tok.startsWith('eyJ') || tok.startsWith('sb_')) {
    throw new Error(
      'Config -> github_token holds a Supabase key, not a GitHub token. GitHub tokens begin ' +
      'ghp_, github_pat_ or gho_. Nothing was dispatched.');
  }
  if (/\s/.test(tok)) {
    throw new Error('Config -> github_token has whitespace in it - it was probably pasted with a ' +
                    'line break. Nothing was dispatched.');
  }
}

return $input.all();

// THE FOUR STAGES, IN ORDER.
//
// Learning is sequential and each stage needs the one before it: nothing can
// be measured from a day that has not settled, nothing fitted from accuracy
// that has not been measured, nothing predicted from a fit that does not
// exist. GitHub runs dispatched workflows concurrently, so dispatching all
// four at once would race - the fit would read yesterday's accuracy and the
// prediction would read no fit at all.
//
// So they are dispatched with a wait between them, long enough for the one
// before to finish on this repo's data sizes. A stage that is skipped is
// skipped on purpose: `only` in the webhook body runs one of them.
const cfg = $('Config').first().json ?? {};
const body = $input.first()?.json ?? {};

const STAGES = [
  { stage: 'evidence',   file: 'databank.yml',        why: 'freeze the days that have settled since last time' },
  { stage: 'accuracy',   file: 'skill.yml',           why: 'measure how wrong each model was on them' },
  { stage: 'correction', file: 'weather_model.yml',   why: 'refit the desk\'s own correction per city' },
  { stage: 'prediction', file: 'model_forecast.yml',  why: 'produce the corrected forward forecast' },
];

const only = String(body.only ?? '').trim();
const wanted = only ? STAGES.filter((s) => s.stage === only || s.file === only) : STAGES;
if (only && !wanted.length) {
  throw new Error(
    `"${only}" is not a stage. Use one of: ${STAGES.map((s) => s.stage).join(', ')} - or send no ` +
    `"only" at all to run the whole chain in order.`);
}

const owner = String(cfg.github_owner).trim();
const repo  = String(cfg.github_repo).trim();
const ref   = String(cfg.github_ref || 'main').trim();
const waitS = Math.max(0, Number(cfg.seconds_between_stages ?? 240));

return wanted.map((s, i) => ({
  json: {
    ...s,
    index: i,
    of: wanted.length,
    ref,
    url: `https://api.github.com/repos/${owner}/${repo}/actions/workflows/${s.file}/dispatches`,
    runs_url: `https://github.com/${owner}/${repo}/actions/workflows/${s.file}`,
    // n8n's HTTP node has no per-item delay, so the wait is expressed as a
    // batch interval on the request node: one item per batch, waitS between.
    wait_seconds: waitS,
  },
}));

// DID GITHUB TAKE IT?
//
// A dispatch that succeeds returns 204 with an EMPTY BODY, so "no output" is
// the success case here and cannot be used as the failure test. The failures
// all return a body, and each one means something specific and fixable.
const cfg = $('Config').first().json ?? {};
const asked = $('Build dispatches').all().map((i) => i.json);
const results = $('Dispatch').all().map((i) => i.json ?? {});

const problems = [];
for (const r of results) {
  if (!r || typeof r !== 'object' || !r.message) continue;
  problems.push(String(r.message));
}

if (problems.length) {
  const m = problems[0];
  if (/Bad credentials/i.test(m)) {
    throw new Error(
      'GitHub rejected the token (Bad credentials). It is wrong, revoked, or expired. ' +
      'Replace Config -> github_token with a token that has "actions: write" on ' +
      `${cfg.github_owner}/${cfg.github_repo}. Nothing was started.`);
  }
  if (/Resource not accessible|must have admin|permission/i.test(m)) {
    throw new Error(
      'The token is valid but is not allowed to start workflows. A fine-grained token needs ' +
      'Repository permissions -> Actions: Read and write on ' +
      `${cfg.github_owner}/${cfg.github_repo}. Nothing was started.`);
  }
  if (/Not Found/i.test(m)) {
    throw new Error(
      `GitHub says Not Found. Either ${cfg.github_owner}/${cfg.github_repo} is wrong, or one of ` +
      'the workflow files does not exist on the default branch, or the token cannot see the ' +
      'repository at all. A workflow can only be dispatched if it carries workflow_dispatch AND ' +
      'exists on the branch in Config -> github_ref. Nothing was started.');
  }
  if (/No ref found|does not have a workflow/i.test(m)) {
    throw new Error(
      `Config -> github_ref is "${cfg.github_ref || 'main'}" and GitHub cannot find it, or the ` +
      'workflow does not exist on it. Set it to the branch the Actions actually live on. ' +
      'Nothing was started.');
  }
  throw new Error(`GitHub refused the dispatch: ${m}. Nothing was started.`);
}

const started = asked.map((a) => a.stage);
const summary =
  `AD4 P2.1: asked GitHub to run ${started.length} learning stage(s) in order: ${started.join(' -> ')}. ` +
  `Each is queued ${asked[0]?.wait_seconds ?? 0}s apart so a stage reads what the one before it wrote. ` +
  `Watch them at ${asked[0]?.runs_url ?? 'the repository Actions tab'}.`;

return [{ json: {
  summary,
  status: 'ok',
  rows: started.length,
  stages: asked.map((a) => ({ stage: a.stage, file: a.file, why: a.why, runs_url: a.runs_url })),
  log: {
    p_job: 'P2.1_relearn',
    p_status: 'ok',
    p_rows: started.length,
    p_detail: { stages: started, summary, trigger: $execution.mode, execution_id: $execution.id },
  },
}}];
